import { expect, test } from '../fixtures';

test('Logout', async ({ page }) => {
  await test.step('Sign out', async () => {
    await page.goto('/auth/logout');
  });

  await test.step('The logged-out message is shown [code]', async () => {
    await expect(page.locator('.alert-success')).toContainText('Logged out');
  });

  await test.step('The Login link is shown again, the member is signed out [code]', async () => {
    await expect(page.getByRole('link', { name: 'Login', exact: true })).toBeVisible();
  });
});
